"""Reference -> CLI, generated by walking the real ``oaken`` argparse parser.

The page is built from :func:`oaken_cli.main.build_parser`, not a hand-written copy: every command,
its options and the exit codes come from the definition the CLI actually runs, so the reference
cannot drift from the tool. Run with ``uv run`` so ``oaken`` is importable.
"""

from __future__ import annotations

import argparse

import generated
from model import BuildError, Config, Page, page_from_meta

PAGE_ID = "reference/cli"

# The stable exit-code contract (mirrors oaken_cli.exits.ExitCode). Kept here as the documented
# meaning; the generator asserts the names below exist in the enum so the two cannot diverge.
EXIT_CODES = [
    (0, "ok", "The command succeeded."),
    (1, "error", "The operation ran and failed, or an unexpected error."),
    (2, "usage", "Bad arguments."),
    (3, "core down", 'Core is not running — start it with "oaken start".'),
    (4, "auth", "A bad API token, or a provider that needs re-authorizing."),
    (5, "needs confirmation", "A mutation returned a proposal and was not confirmed."),
]


def _options(parser: argparse.ArgumentParser) -> list[str]:
    """Option flags of one (sub)parser, skipping the inherited global flags and -h."""
    rows: list[str] = []
    for action in parser._actions:  # noqa: SLF001 — argparse exposes no public walk
        if not action.option_strings or action.help == argparse.SUPPRESS:
            continue
        if action.dest in ("help", "url", "token_file", "json", "verbose"):
            continue  # the globals and -h are documented once, below the table
        flags = ", ".join(f"`{s}`" for s in action.option_strings)
        rows.append(f"{flags} — {action.help or ''}")
    return rows


def _positionals(parser: argparse.ArgumentParser) -> list[str]:
    rows: list[str] = []
    for action in parser._actions:  # noqa: SLF001
        if action.option_strings or action.dest in ("help", "command"):
            continue
        if isinstance(action, argparse._SubParsersAction):  # noqa: SLF001
            continue  # listed as its own sections
        name = action.metavar or action.dest
        rows.append(f"`{name}` — {action.help or ''}")
    return rows


def _subparsers(parser: argparse.ArgumentParser) -> dict[str, argparse.ArgumentParser]:
    for action in parser._actions:  # noqa: SLF001
        if isinstance(action, argparse._SubParsersAction):  # noqa: SLF001
            return dict(action.choices)
    return {}


def _command_help(parser: argparse.ArgumentParser) -> dict[str, str]:
    """The one-line help argparse stores for each subcommand (on the parent action)."""
    out: dict[str, str] = {}
    for action in parser._actions:  # noqa: SLF001
        if isinstance(action, argparse._SubParsersAction):  # noqa: SLF001
            for choice in action._choices_actions:  # noqa: SLF001
                out[choice.dest] = choice.help or ""
    return out


def _assert_exit_codes_match() -> None:
    from oaken_cli.exits import ExitCode

    have = {int(c) for c in ExitCode}
    documented = {code for code, _, _ in EXIT_CODES}
    if have != documented:
        raise BuildError(
            f"CLI reference exit codes {sorted(documented)} do not match "
            f"oaken_cli.exits.ExitCode {sorted(have)}"
        )


def build(cfg: Config) -> Page:
    try:
        from oaken_cli.main import build_parser
    except ImportError as exc:
        raise BuildError(f"CLI generator: cannot import the parser: {exc}") from exc
    _assert_exit_codes_match()
    parser = build_parser()
    commands = _subparsers(parser)
    help_of = _command_help(parser)

    lines = [
        "The `oaken` command is a thin client over the local core: every command is one call to a"
        " [registry operation](architecture/operations.md). It holds no logic of its own, so a new"
        " operation is reachable immediately through the generic `oaken operation NAME` fallback,"
        " with no new release. `oaken operation NAME` takes the operation's own fields as flags"
        " (`--describe` lists them), and `oaken PLUGIN VERB` is shorthand for"
        " `oaken operation PLUGIN.VERB`, so a function a plugin offers is a command the moment it"
        " is installed.",
        "",
        "Output is human-readable by default; `--json` gives the machine form on **stdout** (never"
        " sanitized — it is the contract a script reads), while logs and errors go to **stderr**."
        " Text printed to a terminal is stripped of control and escape sequences, because mail is"
        " untrusted.",
        "",
        "## Global options",
        "",
        "These work before or after the command name:",
        "",
        "- `--json` — emit machine-readable JSON instead of text.",
        "- `--url URL` — base URL of a running core (dev override).",
        "- `--token-file PATH` — read the API token from this file (dev override).",
        "- `--verbose`, `-v` — show core log output on stderr (`-v` INFO, `-vv` DEBUG).",
        "",
        "## Commands",
        "",
        "| Command | What it does |",
        "|---|---|",
    ]
    for name in commands:
        lines.append(f"| [`{name}`](#{name}) | {help_of.get(name, '')} |")
    lines += ["", "## Exit codes", "", "| Code | Meaning | When |", "|---|---|---|"]
    for code, meaning, when in EXIT_CODES:
        lines.append(f"| {code} | {meaning} | {when} |")
    lines += ["", "## Command details", ""]
    for name, sub in commands.items():
        lines += _command_section(name, sub, help_of.get(name, ""))

    return page_from_meta(
        PAGE_ID,
        "CLI",
        "\n".join(lines),
        {
            "subtitle": "CLI",
            "lead": "Every `oaken` command, its options and the exit codes — generated by walking"
            " the real command-line parser.",
            "badges": [["text-bg-secondary", "Generated"]],
            "group": "reference",
            "order": 25,
            "description": "The oaken command-line client: commands, options and exit codes.",
        },
        None,
        False,
    )


def _command_section(
    name: str, sub: argparse.ArgumentParser, summary: str, level: int = 3
) -> list[str]:
    lines = [f"{'#' * level} `{name}`", ""]
    blurb = (sub.description or "").strip() or summary
    if blurb:
        lines += [blurb, ""]
    positionals = _positionals(sub)
    options = _options(sub)
    nested = _subparsers(sub)
    if positionals:
        lines += ["Arguments:", ""] + [f"- {p}" for p in positionals] + [""]
    if options:
        lines += ["Options:", ""] + [f"- {o}" for o in options] + [""]
    if not positionals and not options and not nested:
        lines += ["No arguments.", ""]
    nested_help = _command_help(sub)
    for child, parser in nested.items():
        lines += _command_section(f"{name} {child}", parser, nested_help.get(child, ""), level + 1)
    return lines


generated.register(PAGE_ID, build)
